import { DurableObject } from "cloudflare:workers";

const EMBEDDED_INFO_BOOK_B64 = "";

const EXIST_COUNT_URL = "https://sab-tracker.com/api/existcount";

const FANDOM_API = "https://stealabrainrot.fandom.com/api.php";

const LIVE_RARITY_PAGES = [
  { page: "Common", rarity: "Common" },
  { page: "Rare", rarity: "Rare" },
  { page: "Epic", rarity: "Epic" },
  { page: "Legendary", rarity: "Legendary" },
  { page: "Mythic", rarity: "Mythic" },
  { page: "Brainrot_God", rarity: "Brainrot God" },
  { page: "Secret", rarity: "Secret" },
  { page: "OG", rarity: "OG" }
];

const MACHINE_CATEGORY_PAGE = "Category:Machines";
const UPDATE_LOG_PAGE = "Update_Log";
const TRAITS_PAGE = "Traits";

const IGNORED_MACHINE_PAGES = new Set([
  "Template:Steal a Brainrot Wiki/PreloadMachineArticle"
]);



const worker = {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // The ONLY public page is /
    if (url.pathname !== "/") {
      return new Response("Not Found", {
        status: 404,
        headers: {
          "content-type": "text/plain; charset=UTF-8"
        }
      });
    }

    // Load the SAB Info Book.
    let content = await getInfoBook(env, ctx);

    // Update Date / Day / Season live.
    content = injectLiveDate(content);

    // Discover newly-added Brainrots from all rarity pages.
    // Only missing / currently-unreleased entries need individual page fetches.
    try {
      content = await syncLiveBrainrots(content, ctx);
    } catch (error) {
      console.log("Live Brainrot sync failed:", error);
      // Keep serving the static Info Book if Fandom is unavailable.
    }

    // Discover Machines live from Fandom's Category:Machines page.
    try {
      content = await syncLiveMachines(content, ctx);
    } catch (error) {
      console.log("Live Machine sync failed:", error);
      // Keep serving the static machine list if Fandom is unavailable.
    }

    // Refresh the Update Log live from Fandom.
    try {
      content = await syncLiveUpdates(content, ctx);
    } catch (error) {
      console.log("Live Update Log sync failed:", error);
      // Keep serving the static Update Log if Fandom is unavailable.
    }

    // Refresh Traits live from the Fandom Traits page.
    try {
      content = await syncLiveTraits(content, ctx);
    } catch (error) {
      console.log("Live Traits sync failed:", error);
      // Keep serving the static Traits section if Fandom is unavailable.
    }

    // Build rarity lookup from the brainrot database already in the book.
    const rarityMap = buildRarityMap(content);

    // Fetch live exist counts and replace the exist-count section.
    try {
      const existCounts = await getExistCounts(env, rarityMap);

      if (existCounts.length > 0) {
        const liveSection = buildExistCountSection(existCounts);
        content = replaceExistCountSection(content, liveSection);
      }
    } catch (error) {
      console.log("Exist count update failed:", error);
      // If the API fails, leave the rest of the SAB Info Book working.
    }

    return new Response(content, {
      status: 200,
      headers: {
        "content-type": "text/plain; charset=UTF-8",
        "cache-control": "no-store",
        "x-content-type-options": "nosniff"
      }
    });
  }
};


// This named export must remain because the existing Durable Object binding
// is configured with class_name = "EternalGateway".
export class EternalGateway extends DurableObject {
  async fetch(request) {
    return worker.fetch(request, this.env, this.ctx);
  }
}

export default worker;

// ============================================================
// SAB INFO BOOK
// ============================================================

async function getInfoBook(env, ctx) {
  /*
    OPTIONAL:

    If you create a Cloudflare Worker environment variable named:

      SAB_INFO_BOOK_URL

    and set it to the RAW GitHub URL of your SAB Info Book,
    the Worker will use the GitHub copy.

    If you do NOT set it, the embedded copy below is used.
  */

  const remoteUrl = env.SAB_INFO_BOOK_URL?.trim();

  if (remoteUrl) {
    try {
      const cache = caches.default;

      const cacheKey = new Request(remoteUrl, {
        method: "GET"
      });

      let response = await cache.match(cacheKey);

      if (!response) {
        response = await fetch(remoteUrl, {
          headers: {
            "User-Agent": "SAB-Info-Book-Worker/2.0",
            "Accept": "text/plain,*/*"
          },
          cf: {
            cacheTtl: 60,
            cacheEverything: true
          }
        });

        if (response.ok) {
          ctx.waitUntil(
            cache.put(
              cacheKey,
              response.clone()
            )
          );
        }
      }

      if (response?.ok) {
        const text = await response.text();

        if (text.trim()) {
          return text;
        }
      }
    } catch (error) {
      console.log(
        "GitHub SAB Info Book fetch failed, using embedded copy:",
        error
      );
    }
  }

  return decodeBase64Utf8(
    EMBEDDED_INFO_BOOK_B64
  );
}


function decodeBase64Utf8(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);

  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }

  return new TextDecoder("utf-8").decode(bytes);
}


// ============================================================
// LIVE DATE
// ============================================================

function injectLiveDate(content) {
  const now = new Date();
const currentMonth = new Intl.DateTimeFormat("en-US", { month: "long" }).format(now);

  const date = new Intl.DateTimeFormat(
    "en-US",
    {
      timeZone: "America/Chicago",
      year: "numeric",
      month: "long",
      day: "numeric"
    }
  ).format(now);

  const dayOfWeek = new Intl.DateTimeFormat(
    "en-US",
    {
      timeZone: "America/Chicago",
      weekday: "long"
    }
  ).format(now);

  const parts = new Intl.DateTimeFormat(
    "en-US",
    {
      timeZone: "America/Chicago",
      month: "numeric",
      day: "numeric"
    }
  ).formatToParts(now);

  const month = Number(
    parts.find(
      p => p.type === "month"
    )?.value || 1
  );

  const day = Number(
    parts.find(
      p => p.type === "day"
    )?.value || 1
  );

  const dayType =
    dayOfWeek === "Saturday" ||
    dayOfWeek === "Sunday"
      ? "Weekend"
      : "Weekday";

  const season = getSeason(
    month,
    day
  );

  const replacement =
`Live Date:
Date: ${date}
Current Month: ${currentMonth}
Day of Week: ${dayOfWeek}
Day Type: ${dayType}
Season: ${season}`;

  const pattern =
    /Live Date:\s*\r?\nDate:[^\r\n]*\r?\n(?:Current Month:[^\r\n]*\r?\n)?Day of Week:[^\r\n]*\r?\nDay Type:[^\r\n]*\r?\nSeason:[^\r\n]*/i;

  if (pattern.test(content)) {
    return content.replace(
      pattern,
      replacement
    );
  }

  return (
    replacement +
    "\n\n" +
    content
  );
}


function getSeason(month, day) {
  if (
    month === 12 ||
    month === 1 ||
    month === 2
  ) {
    return "Winter";
  }

  if (
    month >= 3 &&
    month <= 5
  ) {
    return "Spring";
  }

  if (
    month >= 6 &&
    month <= 8
  ) {
    return "Summer";
  }

  return "Fall";
}


// ============================================================
// RARITY LOOKUP
// ============================================================

function buildRarityMap(content) {
  /*
    Reads entries already inside your SAB Info Book:

      Meowl
      Rarity: OG | Income: ...

    and creates:

      meowl -> OG

    This lets the exist-count API show [OG], [Secret], etc.
    even if sab-tracker does not send a rarity field.
  */

  const map = new Map();

  const rarityNames = [
    "Common",
    "Rare",
    "Epic",
    "Legendary",
    "Mythic",
    "Brainrot God",
    "Secret",
    "OG"
  ];

  const rarityPattern = rarityNames
    .map(escapeRegExp)
    .join("|");

  const regex = new RegExp(
    "^([^\\r\\n]+)\\r?\\n" +
    "Rarity:\\s*(" +
    rarityPattern +
    ")\\s*\\|",
    "gmi"
  );

  let match;

  while (
    (match = regex.exec(content)) !== null
  ) {
    const name = match[1].trim();
    const rarity = match[2].trim();

    map.set(
      normalizeName(name),
      rarity
    );
  }

  return map;
}


function escapeRegExp(value) {
  return value.replace(
    /[.*+?^${}()|[\]\\]/g,
    "\\$&"
  );
}


function normalizeName(value) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/%([0-9A-F]{2})/gi, (_, hex) => {
      try {
        return String.fromCharCode(
          parseInt(hex, 16)
        );
      } catch {
        return _;
      }
    })
    .replace(/_/g, " ")
    .replace(/[’‘`]/g, "'")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}



// ============================================================
// LIVE BRAINROTS FROM FANDOM
// ============================================================

async function syncLiveBrainrots(content, ctx) {
  /*
    The static Info Book remains the main database.

    Every request checks these live rarity pages:
      Common
      Rare
      Epic
      Legendary
      Mythic
      Brainrot God
      Secret
      OG

    We DO NOT fetch hundreds of individual Brainrot pages every request.
    Instead:
      1. Read the 8 rarity list pages.
      2. Compare their Brainrot names against the Info Book.
      3. Fetch individual pages ONLY for newly discovered entries, or
         entries currently marked "Rarity: Unreleased".
      4. Grab Rarity / Income / Cost / Obtain / Release when available.
      5. Put the live entries directly inside the BRAINROTS section.

    This keeps Worker requests much lighter.
  */

  const existing = getExistingBrainrotEntries(content);

  const rarityResults = await Promise.all(
    LIVE_RARITY_PAGES.map(async source => {
      try {
        const html = await getFandomParsedHtml(
          source.page,
          ctx,
          60
        );

        const names = source.rarity === "OG"
          ? collectOgBrainrotLinks(html)
          : collectRarityBrainrotLinks(html);

        return names.map(item => ({
          ...item,
          rarity: source.rarity
        }));
      } catch (error) {
        console.log(
          `Could not read Fandom rarity page ${source.page}:`,
          error
        );

        return [];
      }
    })
  );

  // Also discover Brainrots directly from the CURRENT update page.
  // This catches brand-new Brainrots before the rarity list pages are updated.
  let updateBrainrots = [];

  try {
    updateBrainrots = await collectCurrentUpdateBrainrots(ctx);
  } catch (error) {
    console.log("Could not discover Brainrots from current update:", error);
  }

  const liveMap = new Map();

  for (const list of rarityResults) {
    for (const item of list) {
      const key = normalizeBrainrotName(item.name);

      if (!key) continue;

      // First valid rarity-page appearance wins.
      if (!liveMap.has(key)) {
        liveMap.set(key, item);
      }
    }
  }

  // Add current-update candidates that were not already found on rarity pages.
  // Rarity is intentionally blank here; the individual Brainrot page supplies it.
  for (const item of updateBrainrots) {
    const key = normalizeBrainrotName(item.name);
    if (!key) continue;

    if (!liveMap.has(key)) {
      liveMap.set(key, item);
    }
  }

  const needsDetails = [];

  for (const [key, item] of liveMap) {
    const old = existing.get(key);

    if (
      !old ||
      old.rarity.toLowerCase() === "unreleased" ||
      old.release.toLowerCase().includes("later today")
    ) {
      needsDetails.push(item);
    }
  }

  /*
    Safety cap:
    If Fandom changes its HTML and our parser accidentally thinks
    hundreds of unrelated links are Brainrots, do not flood the API.
  */
  if (needsDetails.length > 80) {
    console.log(
      `Live Brainrot parser found ${needsDetails.length} possible new entries; refusing mass fetch.`
    );

    return content;
  }

  if (needsDetails.length === 0) {
    return updateBrainrotTotal(content);
  }

  const details = await Promise.all(
    needsDetails.map(async item => {
      try {
        return await getLiveBrainrotDetails(
          item,
          ctx
        );
      } catch (error) {
        console.log(
          `Could not fetch Brainrot page ${item.page}:`,
          error
        );

        return null;
      }
    })
  );

  const valid = details.filter(Boolean);

  if (valid.length === 0) {
    return updateBrainrotTotal(content);
  }

  /*
    If one of our manually-added unreleased entries has now appeared
    on Fandom, remove the old placeholder block before injecting the
    actual live entry.
  */
  for (const item of valid) {
    const old = existing.get(
      normalizeBrainrotName(item.name)
    );

    if (
      old &&
      (
        old.rarity.toLowerCase() === "unreleased" ||
        old.release.toLowerCase().includes("later today")
      )
    ) {
      content = removeStaticBrainrotBlock(
        content,
        item.name
      );
    }
  }

  valid.sort(
    (a, b) =>
      incomeToNumber(a.income) -
      incomeToNumber(b.income)
  );

  const block = valid
    .map(formatLiveBrainrot)
    .join("\n\n");

  content = insertLiveBrainrotsIntoSection(
    content,
    block
  );

  return updateBrainrotTotal(content);
}


async function collectCurrentUpdateBrainrots(ctx) {
  const logHtml = await getFandomParsedHtml(
    UPDATE_LOG_PAGE,
    ctx,
    60
  );

  const lower = logHtml.toLowerCase();
  const currentStart = lower.indexOf('id="current_update"');

  if (currentStart === -1) {
    return [];
  }

  const futureStart = lower.indexOf(
    'id="future_updates"',
    currentStart
  );

  const pastStart = lower.indexOf(
    'id="past_updates"',
    currentStart
  );

  let currentEnd = logHtml.length;

  for (const pos of [futureStart, pastStart]) {
    if (
      pos !== -1 &&
      pos < currentEnd
    ) {
      currentEnd = pos;
    }
  }

  const currentHtml = logHtml.slice(
    currentStart,
    currentEnd
  );

  /*
    Find the current update page.

    Example:
      /wiki/Update_Log/Update_61
  */
  const updateMatch =
    currentHtml.match(
      /href=["']\/wiki\/(Update_Log\/Update_[^"'#?]+)(?:#[^"']*)?["']/i
    );

  if (!updateMatch) {
    return [];
  }

  const updatePage =
    decodeURIComponent(
      updateMatch[1]
    );

  const updateHtml =
    await getFandomParsedHtml(
      updatePage,
      ctx,
      120
    );

  const candidates = [];
  const seen = new Set();

  const rarityPattern =
    "(?:Common|Rare|Epic|Legendary|Mythic|Brainrot\\s*God|Secret|OG)";

  /*
    Update pages list new Brainrots in a format like:

      Brainrot Name   Secret   $172.5M/s

    Instead of blindly accepting every wiki link on the update page,
    only accept a link when the nearby HTML contains BOTH:
      - a valid rarity
      - an income ending in /s

    This prevents event/machine/trait links from being mistaken for
    Brainrots and means Update 61's full Brainrot list can be captured.
  */
  const linkRegex =
    /<a\b[^>]*href=["']\/wiki\/([^"'#?]+)[^"']*["'][^>]*>([\s\S]*?)<\/a>/gi;

  let match;

  while (
    (match = linkRegex.exec(updateHtml)) !== null
  ) {
    let page;

    try {
      page =
        decodeURIComponent(
          match[1]
        );
    } catch {
      page = match[1];
    }

    page = page
      .replace(/\/Gallery$/i, "")
      .trim();

    if (!isPossibleBrainrotPage(page)) {
      continue;
    }

    /*
      Look at a short amount of HTML immediately after the link.
      This is enough to see the displayed rarity/income on Update pages.
    */
    const nearby = updateHtml.slice(
      match.index,
      Math.min(
        updateHtml.length,
        match.index + 700
      )
    );

    const nearbyText =
      cleanWikiValue(nearby);

    const rarityMatch =
      nearbyText.match(
        new RegExp(
          `\\b(${rarityPattern})\\b`,
          "i"
        )
      );

    const incomeMatch =
      nearbyText.match(
        /\$?\s*\d+(?:\.\d+)?\s*(?:K|M|B|T|Q)?\s*\/s\b/i
      );

    if (
      !rarityMatch ||
      !incomeMatch
    ) {
      continue;
    }

    let name =
      cleanWikiValue(
        match[2]
      );

    if (!name) {
      name = page
        .replace(/_/g, " ")
        .trim();
    }

    const key =
      normalizeBrainrotName(name);

    if (
      !key ||
      seen.has(key)
    ) {
      continue;
    }

    seen.add(key);

    candidates.push({
      name,
      page,
      rarity: normalizeRarityName(
        rarityMatch[1]
      )
    });
  }

  /*
    A real update should never need hundreds of individual Brainrot
    page requests. Keep a high enough cap for large updates.
  */
  return candidates.slice(0, 80);
}


function normalizeRarityName(value) {
  const text =
    String(value || "")
      .replace(/\s+/g, " ")
      .trim();

  if (
    /^brainrot\s*god$/i.test(text)
  ) {
    return "Brainrot God";
  }

  if (/^common$/i.test(text)) return "Common";
  if (/^rare$/i.test(text)) return "Rare";
  if (/^epic$/i.test(text)) return "Epic";
  if (/^legendary$/i.test(text)) return "Legendary";
  if (/^mythic$/i.test(text)) return "Mythic";
  if (/^secret$/i.test(text)) return "Secret";
  if (/^og$/i.test(text)) return "OG";

  return text;
}


function getExistingBrainrotEntries(content) {
  const map = new Map();

  const lines = content
    .replace(/\r\n/g, "\n")
    .split("\n");

  for (let i = 0; i < lines.length - 1; i++) {
    const name = lines[i].trim();
    const rarityLine = lines[i + 1].trim();

    if (
      !name ||
      !rarityLine.startsWith("Rarity:")
    ) {
      continue;
    }

    const rarityMatch = rarityLine.match(
      /^Rarity:\s*([^|]+)/
    );

    let release = "";

    for (
      let j = i + 2;
      j < Math.min(lines.length, i + 8);
      j++
    ) {
      const line = lines[j].trim();

      if (line.startsWith("Release:")) {
        release = line.slice(
          "Release:".length
        ).trim();
        break;
      }

      if (
        j > i + 2 &&
        lines[j + 1] &&
        lines[j + 1].trim().startsWith("Rarity:")
      ) {
        break;
      }
    }

    map.set(
      normalizeBrainrotName(name),
      {
        name,
        rarity: rarityMatch
          ? rarityMatch[1].trim()
          : "",
        release
      }
    );
  }

  return map;
}


async function getFandomParsedHtml(
  page,
  ctx,
  ttl = 60
) {
  const url = new URL(FANDOM_API);

  url.searchParams.set(
    "action",
    "parse"
  );

  url.searchParams.set(
    "page",
    page
  );

  url.searchParams.set(
    "prop",
    "text"
  );

  url.searchParams.set(
    "format",
    "json"
  );

  url.searchParams.set(
    "formatversion",
    "2"
  );

  const data = await fetchJsonCached(
    url.toString(),
    ctx,
    ttl
  );

  const html =
    data?.parse?.text ??
    data?.parse?.text?.["*"];

  if (
    typeof html !== "string" ||
    !html.trim()
  ) {
    throw new Error(
      `No parsed HTML returned for ${page}`
    );
  }

  return html;
}


async function fetchJsonCached(
  url,
  ctx,
  ttl
) {
  const cache = caches.default;

  const cacheKey = new Request(
    url,
    {
      method: "GET"
    }
  );

  let response = await cache.match(
    cacheKey
  );

  if (!response) {
    response = await fetch(
      url,
      {
        headers: {
          "User-Agent":
            "SAB-Info-Book-Worker/3.0",
          "Accept":
            "application/json,text/plain,*/*"
        },
        cf: {
          cacheTtl: ttl,
          cacheEverything: true
        }
      }
    );

    if (!response.ok) {
      throw new Error(
        `Fandom returned HTTP ${response.status}`
      );
    }

    if (ctx) {
      ctx.waitUntil(
        cache.put(
          cacheKey,
          response.clone()
        )
      );
    }
  }

  return await response.json();
}


function collectRarityBrainrotLinks(html) {
  const section = getBrainrotListSection(
    html
  );

  return collectWikiLinksFromLists(
    section
  );
}


function collectOgBrainrotLinks(html) {
  /*
    The OG page also contains a large "Brainrots (in order of income)"
    section containing non-OG Brainrots.

    Only use the small "List of OG Brainrots" list.
  */

  const lower =
    html.toLowerCase();

  let position = lower.indexOf(
    "list of"
  );

  if (position !== -1) {
    const ogPosition = lower.indexOf(
      "og",
      position
    );

    const brainrotPosition =
      lower.indexOf(
        "brainrot",
        position
      );

    if (
      ogPosition !== -1 &&
      brainrotPosition !== -1 &&
      ogPosition <
        brainrotPosition + 40
    ) {
      position = Math.min(
        ogPosition,
        brainrotPosition
      );
    }
  }

  if (position === -1) {
    position = lower.indexOf(
      "og brainrots"
    );
  }

  if (position === -1) {
    return [];
  }

  const ulStart = lower.indexOf(
    "<ul",
    position
  );

  if (ulStart === -1) {
    return [];
  }

  const ulEnd = lower.indexOf(
    "</ul>",
    ulStart
  );

  if (ulEnd === -1) {
    return [];
  }

  return collectWikiLinksFromLists(
    html.slice(
      ulStart,
      ulEnd + 5
    )
  );
}


function getBrainrotListSection(html) {
  const lower =
    html.toLowerCase();

  const candidates = [
    'id="brainrots"',
    'id="brainrots_(in_order_of_income)"',
    "brainrots (in order of income)"
  ];

  let start = -1;

  for (const candidate of candidates) {
    start = lower.indexOf(
      candidate
    );

    if (start !== -1) {
      break;
    }
  }

  /*
    Pages such as Common/Rare/Epic can have their first list near
    explanatory text. If a Brainrots heading isn't found, begin at
    the first income-range heading.
  */
  if (start === -1) {
    const incomeHeading =
      lower.search(
        /<h[234][^>]*>[\s\S]{0,300}\$/
      );

    if (incomeHeading !== -1) {
      start = incomeHeading;
    }
  }

  if (start === -1) {
    return "";
  }

  /*
    Stop at the next H2. H3 income ranges stay inside the section.
  */
  const nextH2 = lower.indexOf(
    "<h2",
    start + 20
  );

  if (nextH2 === -1) {
    return html.slice(start);
  }

  return html.slice(
    start,
    nextH2
  );
}


function collectWikiLinksFromLists(html) {
  if (!html) {
    return [];
  }

  const results = [];
  const seen = new Set();

  /*
    Work list-item-by-list-item so we only use the FIRST wiki link
    in each Brainrot bullet. That avoids picking links from notes.
  */
  const liRegex =
    /<li\b[^>]*>([\s\S]*?)<\/li>/gi;

  let liMatch;

  while (
    (liMatch = liRegex.exec(html)) !== null
  ) {
    const li = liMatch[1];

    const linkMatch = li.match(
      /<a\b[^>]*href="\/wiki\/([^"#?]+)"[^>]*>/i
    );

    if (!linkMatch) {
      continue;
    }

    let page;

    try {
      page = decodeURIComponent(
        linkMatch[1]
      );
    } catch {
      page = linkMatch[1];
    }

    page = page
      .replace(
        /\/Gallery$/i,
        ""
      )
      .trim();

    if (!isPossibleBrainrotPage(page)) {
      continue;
    }

    const name = page
      .replace(/_/g, " ")
      .trim();

    const key =
      normalizeBrainrotName(name);

    if (
      !key ||
      seen.has(key)
    ) {
      continue;
    }

    seen.add(key);

    results.push({
      name,
      page
    });
  }

  return results;
}


function isPossibleBrainrotPage(page) {
  if (!page) {
    return false;
  }

  if (page.includes(":")) {
    return false;
  }

  const bad = new Set([
    "Brainrots",
    "Rarities",
    "Common",
    "Rare",
    "Epic",
    "Legendary",
    "Mythic",
    "Brainrot_God",
    "Secret",
    "OG",
    "Update_Log",
    "Machines",
    "Mutations",
    "Traits",
    "Admin_Abuse",
    "Steal_a_Brainrot_Wiki"
  ]);

  return !bad.has(page);
}


async function getLiveBrainrotDetails(
  source,
  ctx
) {
  const html = await getFandomParsedHtml(
    source.page,
    ctx,
    300
  );

  const pageName =
    extractInfoboxTitle(html) ||
    source.name;

  const rarity =
    cleanWikiValue(
      extractInfoboxAny(
        html,
        [
          "rarity"
        ]
      )
    ) ||
    source.rarity;

  /*
    Validate the fetched page against the rarity list that led to it.
    This filters most false-positive links if Fandom changes layouts.
  */
  if (
    rarity &&
    source.rarity &&
    normalizeBrainrotName(rarity) !==
      normalizeBrainrotName(
        source.rarity
      )
  ) {
    return null;
  }

  const income =
    cleanMoneyValue(
      extractInfoboxAny(
        html,
        [
          "income",
          "money",
          "earnings"
        ]
      )
    ) ||
    "Unknown";

  const cost =
    cleanMoneyValue(
      extractInfoboxAny(
        html,
        [
          "cost",
          "price"
        ]
      )
    ) ||
    "Unknown";

  let obtain =
    extractObtainMethod(html) ||
    cleanWikiValue(
      extractInfoboxAny(
        html,
        [
          "obtain",
          "obtained",
          "obtainment",
          "method",
          "source"
        ]
      )
    );

  /*
    Newer Fandom infoboxes can store the source inside Status, e.g.:
      Obtainable (Bee Shop)
      Obtainable (RNG Machine)

    Pull the text inside the parentheses as the Obtain method.
  */
  if (!obtain) {
    const status =
      cleanWikiValue(
        extractInfoboxAny(
          html,
          [
            "status"
          ]
        )
      );

    const statusObtain =
      String(status || "").match(
        /Obtainable\s*\(([^)]+)\)/i
      );

    if (statusObtain) {
      obtain =
        statusObtain[1].trim();
    }
  }

  if (!obtain) {
    obtain = "Unknown";
  }

  const releaseRaw =
    cleanWikiValue(
      extractInfoboxAny(
        html,
        [
          "release",
          "released",
          "release_date",
          "release update",
          "update"
        ]
      )
    );

  const updateMatch =
    String(
      releaseRaw || ""
    ).match(
      /\bUpdate\s+0*(\d+(?:\.\d+)?)\b/i
    );

  const release = updateMatch
    ? `Update ${Number(updateMatch[1])}`
    : "";

  return {
    name: decodeHtmlEntities(
      pageName
    ),
    rarity,
    income,
    cost,
    obtain,
    release
  };
}


function extractInfoboxTitle(html) {
  const patterns = [
    /<h2\b[^>]*class="[^"]*\bpi-title\b[^"]*"[^>]*>([\s\S]*?)<\/h2>/i,
    /<h1\b[^>]*class="[^"]*\bpi-title\b[^"]*"[^>]*>([\s\S]*?)<\/h1>/i
  ];

  for (const pattern of patterns) {
    const match = html.match(
      pattern
    );

    if (match) {
      const value =
        cleanWikiValue(
          match[1]
        );

      if (value) {
        return value;
      }
    }
  }

  return "";
}


function extractInfoboxAny(
  html,
  sources
) {
  for (const source of sources) {
    const value =
      extractInfoboxValue(
        html,
        source
      );

    if (value) {
      return value;
    }
  }

  return "";
}


function extractInfoboxValue(
  html,
  source
) {
  const escaped =
    escapeRegex(source);

  const sourceRegex =
    new RegExp(
      `data-source=["']${escaped}["']`,
      "i"
    );

  const match =
    sourceRegex.exec(html);

  if (!match) {
    return "";
  }

  /*
    PortableInfobox structures differ a little between pages.
    Limit the search to a small chunk after data-source.
  */
  const chunk = html.slice(
    match.index,
    match.index + 2500
  );

  const patterns = [
    /<div\b[^>]*class="[^"]*\bpi-data-value\b[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /<td\b[^>]*class="[^"]*\bpi-data-value\b[^"]*"[^>]*>([\s\S]*?)<\/td>/i
  ];

  for (const pattern of patterns) {
    const valueMatch =
      chunk.match(pattern);

    if (valueMatch) {
      const value =
        cleanWikiValue(
          valueMatch[1]
        );

      if (value) {
        return value;
      }
    }
  }

  return "";
}


function extractObtainMethod(html) {
  const lower =
    html.toLowerCase();

  const phrases = [
    "is/was obtained from the following ways",
    "is obtained from the following ways",
    "was obtained from the following ways",
    "obtained from the following ways"
  ];

  let start = -1;

  for (const phrase of phrases) {
    start = lower.indexOf(
      phrase
    );

    if (start !== -1) {
      break;
    }
  }

  if (start === -1) {
    return "";
  }

  const olStart =
    lower.indexOf(
      "<ol",
      start
    );

  if (olStart === -1) {
    return "";
  }

  const olEnd =
    lower.indexOf(
      "</ol>",
      olStart
    );

  if (olEnd === -1) {
    return "";
  }

  const list = html.slice(
    olStart,
    olEnd + 5
  );

  const firstLi =
    list.match(
      /<li\b[^>]*>([\s\S]*?)<\/li>/i
    );

  if (!firstLi) {
    return "";
  }

  /*
    Usually the first meaningful linked object is the source:
      Red Carpet
      Bee Shop
      RNG Machine
      Lucky Block
      Fuse Machine
      etc.
  */
  const firstLink =
    firstLi[1].match(
      /<a\b[^>]*>([\s\S]*?)<\/a>/i
    );

  if (firstLink) {
    const linked =
      cleanWikiValue(
        firstLink[1]
      );

    if (linked) {
      return linked;
    }
  }

  let text =
    cleanWikiValue(
      firstLi[1]
    );

  text = text.replace(
    /^(?:buying|get(?:ting)?|obtained?|obtain(?:ed)?|from)\s+(?:it\s+)?(?:from\s+)?/i,
    ""
  );

  return text
    .replace(/[.]+$/, "")
    .trim();
}


function cleanWikiValue(value) {
  if (!value) {
    return "";
  }

  return decodeHtmlEntities(
    stripHtml(value)
      .replace(/\s+/g, " ")
      .trim()
  );
}


function stripHtml(value) {
  return String(value)
    .replace(
      /<br\s*\/?>/gi,
      " "
    )
    .replace(
      /<[^>]+>/g,
      " "
    );
}


function decodeHtmlEntities(value) {
  return String(value)
    .replace(/&nbsp;/gi, " ")
    .replace(/&#160;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(
      /&#(\d+);/g,
      (_, n) =>
        String.fromCodePoint(
          Number(n)
        )
    )
    .replace(
      /&#x([0-9a-f]+);/gi,
      (_, n) =>
        String.fromCodePoint(
          parseInt(n, 16)
        )
    );
}


function cleanMoneyValue(value) {
  let text =
    cleanWikiValue(value);

  if (!text) {
    return "";
  }

  /*
    Match the user's Info Book style:
      $600M/s -> 600M/s
      $650B   -> 650B
  */
  return text
    .replace(/\$/g, "")
    .trim();
}


function normalizeBrainrotName(value) {
  let text =
    String(value || "");

  try {
    text =
      decodeURIComponent(text);
  } catch {
    // Already decoded.
  }

  return text
    .normalize("NFKC")
    .replace(/_/g, " ")
    .replace(/[’‘`]/g, "'")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}


function escapeRegex(value) {
  return String(value)
    .replace(
      /[.*+?^${}()|[\]\\]/g,
      "\\$&"
    );
}


function incomeToNumber(value) {
  const text =
    String(value || "")
      .replace(/\$/g, "")
      .replace(/,/g, "")
      .replace(/\/s/gi, "")
      .trim()
      .toUpperCase();

  const match = text.match(
    /^(-?\d+(?:\.\d+)?)\s*([KMBTQ]?)/
  );

  if (!match) {
    return Number.MAX_SAFE_INTEGER;
  }

  const number =
    Number(match[1]);

  const multipliers = {
    "": 1,
    K: 1e3,
    M: 1e6,
    B: 1e9,
    T: 1e12,
    Q: 1e15
  };

  return number *
    (multipliers[
      match[2]
    ] || 1);
}


function removeApostrophes(value) {
  return String(value || "")
    .replace(/[\u0027\u2018\u2019\u02BC\uFF07]/g, "")
    .trim();
}


function formatLiveBrainrot(item) {
  const lines = [
    removeApostrophes(item.name),
    `Rarity: ${item.rarity} | Income: ${item.income} | Cost: ${item.cost}`,
    `Obtain: ${removeApostrophes(item.obtain)}`
  ];

  if (item.release) {
    lines.push(
      `Release: ${item.release}`
    );
  }

  return lines.join("\n");
}


function removeStaticBrainrotBlock(
  content,
  name
) {
  /*
    Compare normalized names rather than exact text.

    This means all of these match the same Brainrot:
      S'more Serat
      S’more Serat
      Smore Serat

    The displayed live name is still passed through removeApostrophes(),
    so apostrophes are never captured in the output.
  */

  const target =
    normalizeBrainrotName(name)
      .replace(/'/g, "");

  const lines =
    content
      .replace(/\r\n/g, "\n")
      .split("\n");

  for (
    let i = 0;
    i < lines.length - 1;
    i++
  ) {
    const candidate =
      normalizeBrainrotName(
        lines[i]
      ).replace(/'/g, "");

    if (
      candidate !== target ||
      !lines[i + 1]
        .trim()
        .startsWith("Rarity:")
    ) {
      continue;
    }

    let end = i + 1;

    while (
      end + 1 < lines.length &&
      lines[end + 1].trim() !== ""
    ) {
      end++;
    }

    /*
      Remove the entire old Brainrot block and one following blank line.
    */
    lines.splice(
      i,
      Math.min(
        lines.length - i,
        end - i + 2
      )
    );

    return lines.join("\n");
  }

  return content;
}


function insertLiveBrainrotsIntoSection(
  content,
  block
) {
  if (!block) {
    return content;
  }

  const heading =
    /BRAINROTS\s*[—–-]\s*Sorted by Income\s*\(\d+\s+total\)\s*\r?\n/i;

  const match =
    heading.exec(content);

  if (!match) {
    return content;
  }

  const insertAt =
    match.index +
    match[0].length;

  const liveHeader =
    "LIVE NEW BRAINROTS — Fandom Sync";

  return (
    content.slice(
      0,
      insertAt
    ) +
    liveHeader +
    "\n" +
    block +
    "\n\n" +
    content.slice(
      insertAt
    )
  );
}


function updateBrainrotTotal(content) {
  /*
    Count all Name + Rarity lines in the BRAINROTS area.
    This also counts newly synced Brainrots.
  */
  const headingRegex =
    /BRAINROTS\s*[—–-]\s*Sorted by Income\s*\(\d+\s+total\)/i;

  const match =
    headingRegex.exec(content);

  if (!match) {
    return content;
  }

  const area =
    content.slice(
      match.index +
      match[0].length
    );

  const count =
    (
      area.match(
        /^Rarity:\s*/gmi
      ) || []
    ).length;

  return content.replace(
    headingRegex,
    `BRAINROTS — Sorted by Income (${count} total)`
  );
}




// ============================================================
// LIVE MACHINES FROM FANDOM
// ============================================================

async function syncLiveMachines(content, ctx) {
  /*
    Pulls the machine category live from:
      https://stealabrainrot.fandom.com/wiki/Category:Machines

    It ignores:
      Template:Steal a Brainrot Wiki/PreloadMachineArticle

    The live machine names replace the contents of the existing:
      MACHINES — Old → New
    section.

    This uses the MediaWiki categorymembers API instead of scraping
    the category HTML, which is more reliable for category pages.
  */

  const machines = await getMachineCategoryMembers(ctx);

  // Keep these current machines present even if Fandom's category
  // page has not categorized them yet.
  const requiredMachines = [
    "RNG Machine",
    "Bee Shop"
  ];

  for (const required of requiredMachines) {
    const exists = machines.some(
      machine =>
        machine.trim().toLowerCase() ===
        required.toLowerCase()
    );

    if (!exists) {
      machines.push(required);
    }
  }

  if (!machines.length) {
    return content;
  }

  return replaceMachinesSection(
    content,
    machines
  );
}


async function getMachineCategoryMembers(ctx) {
  const results = [];
  const seen = new Set();

  let cmcontinue = "";

  for (let page = 0; page < 10; page++) {
    const url = new URL(FANDOM_API);

    url.searchParams.set(
      "action",
      "query"
    );

    url.searchParams.set(
      "list",
      "categorymembers"
    );

    url.searchParams.set(
      "cmtitle",
      MACHINE_CATEGORY_PAGE
    );

    url.searchParams.set(
      "cmlimit",
      "500"
    );

    /*
      Include both normal articles and template namespace entries,
      then explicitly ignore the one template requested by the user.
    */
    url.searchParams.set(
      "cmnamespace",
      "0|10"
    );

    url.searchParams.set(
      "format",
      "json"
    );

    url.searchParams.set(
      "formatversion",
      "2"
    );

    if (cmcontinue) {
      url.searchParams.set(
        "cmcontinue",
        cmcontinue
      );
    }

    const data = await fetchJsonCached(
      url.toString(),
      ctx,
      60
    );

    const members =
      data?.query?.categorymembers || [];

    for (const member of members) {
      let title = String(
        member?.title || ""
      ).trim();

      if (!title) {
        continue;
      }

      if (
        IGNORED_MACHINE_PAGES.has(title)
      ) {
        continue;
      }

      /*
        Ignore all other non-article namespaces too.
        The requested preload template is therefore definitely excluded,
        while the machine list itself stays clean.
      */
      if (
        typeof member.ns === "number" &&
        member.ns !== 0
      ) {
        continue;
      }

      title = title
        .replace(/_/g, " ")
        .trim();

      const key =
        title.toLowerCase();

      if (
        seen.has(key)
      ) {
        continue;
      }

      seen.add(key);
      results.push(title);
    }

    cmcontinue =
      data?.continue?.cmcontinue || "";

    if (!cmcontinue) {
      break;
    }
  }

  return results;
}


function replaceMachinesSection(
  content,
  machines
) {
  const headingRegex =
    /MACHINES\s*[—–-]\s*Old\s*→\s*New\s*\r?\n/i;

  const headingMatch =
    headingRegex.exec(content);

  if (!headingMatch) {
    return content;
  }

  const start =
    headingMatch.index +
    headingMatch[0].length;

  const after =
    content.slice(start);

  const nextSectionRegex =
    /(?:^|\r?\n)(?:LUCKY BLOCKS|UPDATE LOG|BRAINROTS|EXIST COUNTS|MUTATIONS)\b/i;

  const nextMatch =
    nextSectionRegex.exec(after);

  const end =
    nextMatch
      ? start + nextMatch.index
      : content.length;

  const machineBlock =
    machines.join("\n") + "\n\n";

  return (
    content.slice(0, start) +
    machineBlock +
    content.slice(end)
  );
}




// ============================================================
// LIVE UPDATE LOG FROM FANDOM
// ============================================================

async function syncLiveUpdates(content, ctx) {
  /*
    Reads:
      https://stealabrainrot.fandom.com/wiki/Update_Log

    The page contains Current, Future, and Past Update tables.
    Current + Past are included; Future Updates are skipped.

    The table columns include:
      Name | Release Date | Main Features and Description

    Only the update number/name and release date are written into
    the Info Book, using this exact style:

      Update 42	ST PATRICKS	March 14, 2026

    The description/features column is intentionally ignored.
  */

  const html = await getFandomParsedHtml(
    UPDATE_LOG_PAGE,
    ctx,
    60
  );

  const updates = parseUpdateLogTable(
    html
  );

  if (!updates.length) {
    return content;
  }

  return replaceUpdateLogSection(
    content,
    updates
  );
}


function parseUpdateLogTable(html) {
  /*
    The page has:
      Current Update
      Future Updates
      Past Updates

    Include Current + Past.
    Skip Future Updates.

    Output example:
      Update 42	ST PATRICKS	March 14, 2026
  */

  const results = [];
  const seen = new Set();

  const lower = html.toLowerCase();

  const currentStart =
    lower.indexOf('id="current_update"');

  const futureStart =
    lower.indexOf('id="future_updates"');

  const pastStart =
    lower.indexOf('id="past_updates"');

  const sections = [];

  if (currentStart !== -1) {
    let currentEnd = html.length;

    if (
      futureStart !== -1 &&
      futureStart > currentStart
    ) {
      currentEnd = futureStart;
    } else if (
      pastStart !== -1 &&
      pastStart > currentStart
    ) {
      currentEnd = pastStart;
    }

    sections.push(
      html.slice(
        currentStart,
        currentEnd
      )
    );
  }

  if (pastStart !== -1) {
    sections.push(
      html.slice(
        pastStart
      )
    );
  }

  // Fallback if Fandom changes section IDs:
  // parse the whole page, but remove the Future section first.
  if (sections.length === 0) {
    let safeHtml = html;

    if (
      futureStart !== -1 &&
      pastStart !== -1 &&
      pastStart > futureStart
    ) {
      safeHtml =
        html.slice(0, futureStart) +
        html.slice(pastStart);
    }

    sections.push(safeHtml);
  }

  for (const section of sections) {
    const rowRegex =
      /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;

    let rowMatch;

    while (
      (rowMatch = rowRegex.exec(section)) !== null
    ) {
      const rowHtml = rowMatch[1];

      const cells = [];
      const tdRegex =
        /<td\b[^>]*>([\s\S]*?)<\/td>/gi;

      let tdMatch;

      while (
        (tdMatch = tdRegex.exec(rowHtml)) !== null
      ) {
        cells.push(tdMatch[1]);
      }

      if (cells.length < 2) {
        continue;
      }

      const nameCellHtml = cells[0];
      const dateCellHtml = cells[1];

      /*
        Use visible text instead of the URL because mini-updates use:
          /Update_52#Update_52.5
          /Update_52#Update_52.75
      */
      const nameCellText =
        cleanWikiValue(
          nameCellHtml
        );

      const updateMatch =
        nameCellText.match(
          /\bUpdate\s+0*(\d+(?:\.\d+)?)\b/i
        );

      if (!updateMatch) {
        continue;
      }

      const updateNumber =
        normalizeUpdateNumber(
          updateMatch[1]
        );

      const boldMatch =
        nameCellHtml.match(
          /<b\b[^>]*>([\s\S]*?)<\/b>/i
        );

      if (!boldMatch) {
        continue;
      }

      const updateName =
        cleanWikiValue(
          boldMatch[1]
        );

      const releaseDate =
        normalizeUpdateDate(
          cleanWikiValue(
            dateCellHtml
          )
        );

      if (
        !updateName ||
        !releaseDate
      ) {
        continue;
      }

      const key =
        `Update ${updateNumber}`;

      if (seen.has(key)) {
        continue;
      }

      seen.add(key);

      results.push({
        number: updateNumber,
        name: updateName,
        date: releaseDate
      });
    }
  }

  results.sort(
    (a, b) =>
      Number(a.number) -
      Number(b.number)
  );

  return results;
}


function normalizeUpdateNumber(value) {
  const number =
    Number(
      String(value)
        .replace(/^0+/, "") || "0"
    );

  if (!Number.isFinite(number)) {
    return String(value);
  }

  return String(number);
}


function normalizeUpdateDate(value) {
  const text =
    String(value || "")
      .replace(
        /(\d+)(st|nd|rd|th)\b/gi,
        "$1"
      )
      .replace(/\s+/g, " ")
      .trim();

  const match =
    text.match(
      /\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2}),?\s+(\d{4})\b/i
    );

  if (!match) {
    return "";
  }

  const month =
    match[1].charAt(0).toUpperCase() +
    match[1].slice(1).toLowerCase();

  const day =
    Number(match[2]);

  const year =
    match[3];

  return `${month} ${day}, ${year}`;
}


function replaceUpdateLogSection(
  content,
  updates
) {
  const headingRegex =
    /UPDATE LOG\s*\r?\n(?:-+\s*\r?\n)?/i;

  const headingMatch =
    headingRegex.exec(content);

  if (!headingMatch) {
    return content;
  }

  const start =
    headingMatch.index +
    headingMatch[0].length;

  const after =
    content.slice(start);

  /*
    The next major section after UPDATE LOG is normally BRAINROTS.
  */
  const nextSectionRegex =
    /(?:^|\r?\n)BRAINROTS\s*[—–-]/i;

  const nextMatch =
    nextSectionRegex.exec(after);

  const end =
    nextMatch
      ? start + nextMatch.index
      : content.length;

  const updateLines =
    updates
      .map(
        item =>
          `Update ${item.number}\t${item.name}\t${item.date}`
      )
      .join("\n");

  return (
    content.slice(
      0,
      start
    ) +
    updateLines +
    "\n\n" +
    content.slice(
      end
    )
  );
}




// ============================================================
// LIVE TRAITS FROM FANDOM
// ============================================================

async function syncLiveTraits(content, ctx) {
  const html = await getFandomParsedHtml(
    TRAITS_PAGE,
    ctx,
    60
  );

  const groups = parseTraitsPage(html);

  if (!groups.length) {
    return content;
  }

  return replaceTraitsSection(
    content,
    groups
  );
}


function parseTraitsPage(html) {
  const results = [];

  /*
    Do NOT depend on id="traits".
    Fandom can change/remove section IDs in API parsed HTML.

    Instead, scan every fandom-table and keep only tables whose
    header contains both "Name" and "Multiplier".
  */
  const tableRegex =
    /<table\b[^>]*class=["'][^"']*\bfandom-table\b[^"']*["'][^>]*>([\s\S]*?)<\/table>/gi;

  let tableMatch;

  while (
    (tableMatch = tableRegex.exec(html)) !== null
  ) {
    const tableHtml = tableMatch[1];

    const headerText =
      cleanWikiValue(
        tableHtml.match(
          /<tr\b[^>]*>([\s\S]*?)<\/tr>/i
        )?.[1] || ""
      ).toLowerCase();

    if (
      !headerText.includes("name") ||
      !headerText.includes("multiplier")
    ) {
      continue;
    }

    const captionMatch =
      tableHtml.match(
        /<caption\b[^>]*>([\s\S]*?)<\/caption>/i
      );

    let groupName =
      captionMatch
        ? cleanWikiValue(captionMatch[1])
        : "Traits";

    groupName = groupName
      .replace(/\s+Traits$/i, "")
      .trim();

    const traits = [];
    const rowRegex =
      /<tr\b[^>]*>([\s\S]*?)<\/tr>/gi;

    let rowMatch;

    while (
      (rowMatch = rowRegex.exec(tableHtml)) !== null
    ) {
      const rowHtml = rowMatch[1];
      const cells = [];

      const cellRegex =
        /<td\b[^>]*>([\s\S]*?)<\/td>/gi;

      let cellMatch;

      while (
        (cellMatch = cellRegex.exec(rowHtml)) !== null
      ) {
        cells.push(cellMatch[1]);
      }

      if (cells.length < 2) {
        continue;
      }

      let name = "";

      const traitSpan =
        cells[0].match(
          /<span\b[^>]*class=["'][^"']*\btrait\b[^"']*["'][^>]*>([\s\S]*?)<\/span>/i
        );

      if (traitSpan) {
        name =
          cleanWikiValue(
            traitSpan[1]
          );
      }

      if (!name) {
        const bold =
          cells[0].match(
            /<b\b[^>]*>([\s\S]*?)<\/b>/i
          );

        if (bold) {
          name =
            cleanWikiValue(
              bold[1]
            );
        }
      }

      if (!name) {
        name =
          cleanWikiValue(
            cells[0]
          );
      }

      name = name.trim();

      if (
        !name ||
        /^name$/i.test(name)
      ) {
        continue;
      }

      let multiplier =
        cleanWikiValue(
          cells[1]
        )
          .replace(/×/g, "x")
          .replace(/\s+/g, "")
          .trim();

      if (
        !multiplier ||
        !/\d/.test(multiplier)
      ) {
        continue;
      }

      let obtain = "";

      if (cells.length >= 3) {
        obtain =
          extractTraitObtain(
            cells[2]
          );
      }

      traits.push({
        name,
        multiplier,
        obtain
      });
    }

    if (traits.length) {
      results.push({
        group: groupName || "Other",
        traits
      });
    }
  }

  return results;
}


function extractTraitObtain(cellHtml) {
  const bold =
    cellHtml.match(
      /<b\b[^>]*>([\s\S]*?)<\/b>/i
    );

  let value = "";

  if (bold) {
    value = cleanWikiValue(
      bold[1]
    );
  }

  if (!value) {
    value = cleanWikiValue(
      cellHtml
    );
  }

  return value
    .replace(/[.]+$/, "")
    .replace(/\s*\/\s*/g, " / ")
    .replace(/\s+/g, " ")
    .trim();
}


function buildTraitsSection(groups) {
  const lines = [
    "Traits",
    "-----------"
  ];

  for (const group of groups) {
    lines.push("");

    let groupName = group.group;

    // Make category headings read like "OG Traits", "AA Exclusive Traits", etc.
    if (!/\btraits$/i.test(groupName)) {
      groupName += " Traits";
    }

    lines.push(groupName);

    for (const trait of group.traits) {
      let line = trait.name;

      if (trait.multiplier) {
        line += ` — ${trait.multiplier}`;
      }

      if (trait.obtain) {
        line += ` — ${trait.obtain}`;
      }

      lines.push(line);
    }
  }

  return lines.join("\n");
}


function replaceTraitsSection(
  content,
  groups
) {
  const newSection =
    buildTraitsSection(groups);

  /*
    Replace an existing TRAITS section if present.
  */
  const traitsHeading =
    /(?:^|\r?\n)Traits(?:\s*[—–-][^\r\n]*)?\s*\r?\n(?:-+\s*\r?\n)?/i;

  const match =
    traitsHeading.exec(content);

  if (match) {
    const sectionStart =
      match.index +
      (
        match[0].startsWith("\r\n")
          ? 2
          : (
              match[0].startsWith("\n")
                ? 1
                : 0
            )
      );

    const searchFrom =
      sectionStart +
      match[0].replace(/^\r?\n/, "").length;

    const rest =
      content.slice(searchFrom);

    const nextHeading =
      /(?:^|\r?\n)(?:MUTATIONS|MACHINES|LUCKY BLOCKS|UPDATE LOG|BRAINROTS|EXIST COUNTS|RARITIES|DEVELOPMENT CREDITS|ADMIN WAR|TRAITS)\b/i;

    const next =
      nextHeading.exec(rest);

    const sectionEnd =
      next
        ? searchFrom + next.index
        : content.length;

    return (
      content.slice(0, sectionStart) +
      newSection +
      "\n\n" +
      content.slice(sectionEnd).replace(/^\s+/, "")
    );
  }

  /*
    No TRAITS section exists yet.
    Insert immediately before MUTATIONS.
  */
  const mutationsMatch =
    /(?:^|\r?\n)MUTATIONS(?:\s*[—–-][^\r\n]*)?\s*\r?\n/i.exec(
      content
    );

  if (mutationsMatch) {
    const insertAt =
      mutationsMatch.index +
      (
        mutationsMatch[0].startsWith("\r\n")
          ? 2
          : (
              mutationsMatch[0].startsWith("\n")
                ? 1
                : 0
            )
      );

    return (
      content.slice(0, insertAt) +
      newSection +
      "\n\n" +
      content.slice(insertAt)
    );
  }

  /*
    Final fallback: append it.
  */
  return (
    content.trimEnd() +
    "\n\n" +
    newSection +
    "\n"
  );
}


// ============================================================
// EXIST COUNTS
// ============================================================

async function getExistCounts(
  env,
  rarityMap
) {
  /*
    You can optionally override the URL with a Worker variable:

      EXIST_COUNT_URL

    Otherwise:
      https://sab-tracker.com/api/existcount

    is used.
  */

  const endpoint =
    env.EXIST_COUNT_URL?.trim() ||
    EXIST_COUNT_URL;

  const response = await fetch(
    endpoint,
    {
      headers: {
        "User-Agent":
          "Mozilla/5.0 (Windows NT 10.0; Win64; x64) " +
          "AppleWebKit/537.36 Chrome/149 Safari/537.36",
        "Accept":
          "application/json,text/plain,*/*",
        "Referer":
          "https://sab-tracker.com/"
      },
      cf: {
        cacheTtl: 30,
        cacheEverything: true
      }
    }
  );

  if (!response.ok) {
    throw new Error(
      `sab-tracker returned HTTP ${response.status}`
    );
  }

  const rawText = await response.text();

  let data;

  try {
    data = JSON.parse(rawText);
  } catch {
    throw new Error(
      "sab-tracker did not return valid JSON"
    );
  }

  const rawEntries =
    extractExistEntries(data);

  const cleaned = [];
  const seen = new Map();

  for (const item of rawEntries) {
    if (!item) continue;

    const name = findName(item);

    if (!name) {
      continue;
    }

    const exist = findExistCount(item);

    if (!Number.isFinite(exist)) {
      continue;
    }

    let rarity = findRarity(item);

    if (!rarity) {
      rarity = rarityMap.get(
        normalizeName(name)
      ) || "";
    }

    const entry = {
      name: cleanDisplayName(name),
      exist,
      rarity
    };

    const key = normalizeName(
      entry.name
    );

    /*
      If the API accidentally contains the same Brainrot twice,
      keep the entry with the lowest valid exist count.
    */
    if (!seen.has(key)) {
      seen.set(key, entry);
    } else {
      const old = seen.get(key);

      if (entry.exist < old.exist) {
        seen.set(key, entry);
      }
    }
  }

  for (const entry of seen.values()) {
    cleaned.push(entry);
  }

  cleaned.sort(
    (a, b) => {
      if (a.exist !== b.exist) {
        return a.exist - b.exist;
      }

      return a.name.localeCompare(
        b.name
      );
    }
  );

  return cleaned;
}


// ============================================================
// API RESPONSE PARSER
// ============================================================

function extractExistEntries(data) {
  /*
    Supports many possible JSON formats, including:

    [
      {
        name: "...",
        totalExist: 78
      }
    ]

    {
      data: [...]
    }

    {
      results: [...]
    }

    {
      "Headless Horseman": 78,
      "Meowl": 1234
    }

    {
      "Headless Horseman": {
        totalExist: 78,
        rarity: "OG"
      }
    }

    and nested variants.
  */

  const output = [];
  const visited = new Set();

  function walk(value, inheritedName = "") {
    if (
      value === null ||
      value === undefined
    ) {
      return;
    }

    if (
      typeof value !== "object"
    ) {
      if (
        inheritedName &&
        isNumericLike(value)
      ) {
        output.push({
          name: inheritedName,
          totalExist: value
        });
      }

      return;
    }

    if (visited.has(value)) {
      return;
    }

    visited.add(value);

    if (Array.isArray(value)) {
      for (const item of value) {
        walk(item);
      }

      return;
    }

    const possibleName =
      findName(value) ||
      inheritedName;

    const possibleCount =
      findExistCount(value);

    if (
      possibleName &&
      Number.isFinite(
        possibleCount
      )
    ) {
      output.push({
        ...value,
        name: possibleName,
        totalExist: possibleCount
      });

      return;
    }

    for (
      const [key, child]
      of Object.entries(value)
    ) {
      /*
        If an object key itself looks like a Brainrot name,
        carry the key down as the possible name.
      */

      let nextName = possibleName;

      if (
        !nextName &&
        looksLikeBrainrotKey(key)
      ) {
        nextName = key;
      }

      if (
        isNumericLike(child) &&
        looksLikeBrainrotKey(key)
      ) {
        output.push({
          name: key,
          totalExist: child
        });

        continue;
      }

      walk(
        child,
        nextName
      );
    }
  }

  walk(data);

  return output;
}


function looksLikeBrainrotKey(key) {
  const lowered = String(key)
    .trim()
    .toLowerCase();

  const ignored = new Set([
    "data",
    "results",
    "result",
    "brainrots",
    "items",
    "counts",
    "existcounts",
    "exist_counts",
    "response",
    "success",
    "status",
    "message",
    "updated",
    "updatedat",
    "updated_at",
    "timestamp",
    "total"
  ]);

  return (
    lowered.length >= 1 &&
    !ignored.has(lowered)
  );
}


function findName(item) {
  if (
    !item ||
    typeof item !== "object"
  ) {
    return "";
  }

  const keys = [
    "name",
    "Name",
    "brainrot",
    "Brainrot",
    "brainrotName",
    "brainrot_name",
    "BrainrotName",
    "title",
    "Title",
    "displayName",
    "display_name"
  ];

  for (const key of keys) {
    const value = item[key];

    if (
      typeof value === "string" &&
      value.trim()
    ) {
      return value.trim();
    }
  }

  return "";
}


function findExistCount(item) {
  if (
    !item ||
    typeof item !== "object"
  ) {
    return NaN;
  }

  // Total Exist = all normal + mutation variants combined.
  // Do NOT include income, last_updated, or unrelated fields.
  const countFields = [
    "normal",
    "gold",
    "diamond",
    "rainbow",
    "bloodrot",
    "candy",
    "lava",
    "galaxy",
    "yin_yang",
    "radioactive",
    "cursed",
    "divine",
    "cyber",
    "phantom",
    "crystal"
  ];

  let total = 0;
  let foundAny = false;

  for (const field of countFields) {
    if (
      Object.prototype.hasOwnProperty.call(
        item,
        field
      )
    ) {
      const value = parseNumber(
        item[field]
      );

      if (Number.isFinite(value)) {
        total += value;
        foundAny = true;
      }
    }
  }

  if (!foundAny) {
    return NaN;
  }

  return total;
}


function findRarity(item) {
  if (
    !item ||
    typeof item !== "object"
  ) {
    return "";
  }

  const keys = [
    "rarity",
    "Rarity",
    "tier",
    "Tier"
  ];

  for (const key of keys) {
    const value = item[key];

    if (
      typeof value === "string" &&
      value.trim()
    ) {
      return value
        .replace(/_/g, " ")
        .trim();
    }
  }

  return "";
}


function parseNumber(value) {
  if (
    typeof value === "number"
  ) {
    return value;
  }

  if (
    typeof value !== "string"
  ) {
    return NaN;
  }

  const cleaned = value
    .replace(/,/g, "")
    .replace(/[^\d.-]/g, "")
    .trim();

  if (!cleaned) {
    return NaN;
  }

  return Number(cleaned);
}


function isNumericLike(value) {
  return Number.isFinite(
    parseNumber(value)
  );
}


function cleanDisplayName(value) {
  let result = String(value || "");

  try {
    result = decodeURIComponent(
      result
    );
  } catch {
    // Keep original if it was not URL encoded.
  }

  return result
    .replace(/_/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}


// ============================================================
// BUILD LIVE EXIST-COUNT SECTION
// ============================================================

function buildExistCountSection(
  entries
) {
  const lines = [
    "EXIST COUNTS - Rarest → Most Common (live)",
    "",
    "Source: sab-tracker.com/api/existcount",
    "Sorted rarest → most common.",
    ""
  ];

  entries.forEach(
    (item, index) => {
      const formattedCount =
        Math.trunc(item.exist)
          .toLocaleString("en-US");

      const rarity =
        item.rarity
          ? ` [${item.rarity}]`
          : "";

      lines.push(
        `${index + 1}. ` +
        `${item.name}: ` +
        `Total Exist ${formattedCount}` +
        rarity
      );
    }
  );

  return lines.join("\n");
}


// ============================================================
// REPLACE EXIST-COUNT SECTION
// ============================================================

function replaceExistCountSection(
  content,
  newSection
) {
  const startRegex =
    /EXIST COUNTS\s*[-—–]\s*Rarest\s*→\s*Most Common\s*\(live\)/i;

  const startMatch =
    startRegex.exec(content);

  if (!startMatch) {
    /*
      If the section somehow disappeared,
      insert it immediately before MUTATIONS.
    */

    const mutationRegex =
      /MUTATIONS\s*[—–-]\s*Old\s*→\s*New/i;

    const mutationMatch =
      mutationRegex.exec(content);

    if (!mutationMatch) {
      return (
        content.trimEnd() +
        "\n\n" +
        newSection +
        "\n"
      );
    }

    return (
      content.slice(
        0,
        mutationMatch.index
      ) +
      newSection +
      "\n\n" +
      content.slice(
        mutationMatch.index
      )
    );
  }

  const sectionStart =
    startMatch.index;

  const afterStart =
    sectionStart +
    startMatch[0].length;

  const remaining =
    content.slice(afterStart);

  const mutationRegex =
    /MUTATIONS\s*[—–-]\s*Old\s*→\s*New/i;

  const mutationMatch =
    mutationRegex.exec(remaining);

  if (!mutationMatch) {
    return (
      content.slice(
        0,
        sectionStart
      ) +
      newSection +
      "\n"
    );
  }

  const sectionEnd =
    afterStart +
    mutationMatch.index;

  return (
    content.slice(
      0,
      sectionStart
    ) +
    newSection +
    "\n\n" +
    content.slice(
      sectionEnd
    )
  );
}
